-- Display label only; graph, defaults and block code are unchanged.
BEGIN;
SET LOCAL timezone='UTC';
SET LOCAL lock_timeout='2s';
SET LOCAL statement_timeout='8s';
SELECT id FROM public.auto_workflows WHERE id IN(157,207,244,245) ORDER BY id FOR UPDATE;
DO $label$
BEGIN
IF EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE name='migration_v413_comment_like_label') THEN RAISE EXCEPTION 'v413 already applied'; END IF;
