IF (SELECT md5((to_jsonb(w)-'variables_schema'-'updated_at')::text) FROM public.auto_workflows w WHERE id=207) IS DISTINCT FROM 'bf1f4ee8358b5fd9d25376b62fa4271f' OR (SELECT variables_schema FROM public.auto_workflows WHERE id=207) IS DISTINCT FROM '[{"label":"URL bài post","name":"targetUrl","type":"string"},{"label":"Like bài post khi comment","name":"enablePostLike","type":"boolean"},{"label":"Danh sách biến thể nội dung comment","name":"commentVariants","type":"array"},{"label":"Ảnh comment theo lượt","name":"commentImageBatches","type":"array"},{"default":false,"label":"Chạy bằng Page","name":"runAsPage","type":"boolean"},{"default":"","label":"ID Page","name":"runAsPageUid","type":"string"},{"default":"","label":"Tên Page","name":"runAsPageName","type":"string"},{"default":false,"label":"Đã chuyển Page trong lượt","name":"pageIdentityReady","type":"boolean"},{"default":"","label":"Danh tính ban đầu","name":"originalIdentityName","type":"string"},{"default":false,"label":"Chỉ chuyển về danh tính ban đầu","name":"pageIdentityRestoreOnly","type":"boolean"},{"default":true,"label":"Chuyển về sau target (chạy thử)","name":"pageIdentityRestoreAfterTarget","type":"boolean"}]'::jsonb THEN RAISE EXCEPTION 'v413 workflow 207 post-state mismatch'; END IF;
