IF (SELECT md5((to_jsonb(w)-'variables_schema'-'updated_at')::text) FROM public.auto_workflows w WHERE id=245) IS DISTINCT FROM '220eb6f36de047569ee015798146b51b' OR (SELECT variables_schema FROM public.auto_workflows WHERE id=245) IS DISTINCT FROM '[{"label":"URL target (group/profile/page/post)","name":"targetUrl","type":"string"},{"label":"Số bài comment / target","name":"postsPerTarget","type":"number"},{"label":"Like bài post khi comment","name":"enablePostLike","type":"boolean"},{"label":"Danh sách biến thể nội dung comment","name":"commentVariants","type":"array"},{"default":false,"label":"Lọc từ khoá bài viết","name":"isFindPostByKeywords","type":"boolean"},{"default":"","label":"Từ khoá bài viết","name":"postKeywords","type":"string"},{"default":false,"label":"Lọc ý nghĩa bài viết bằng AI","name":"isFindPostByContentAI","type":"boolean"},{"default":"","label":"Ý nghĩa bài viết","name":"postContentAI","type":"string"},{"default":false,"label":"Chạy bằng Page","name":"runAsPage","type":"boolean"},{"default":"","label":"ID Page","name":"runAsPageUid","type":"string"},{"default":"","label":"Tên Page","name":"runAsPageName","type":"string"},{"default":false,"label":"Đã chuyển Page trong lượt","name":"pageIdentityReady","type":"boolean"},{"default":"","label":"Danh tính ban đầu","name":"originalIdentityName","type":"string"},{"default":false,"label":"Chỉ chuyển về danh tính ban đầu","name":"pageIdentityRestoreOnly","type":"boolean"},{"default":true,"label":"Chuyển về sau target (chạy thử)","name":"pageIdentityRestoreAfterTarget","type":"boolean"}]'::jsonb THEN RAISE EXCEPTION 'v413 workflow 245 post-state mismatch'; END IF;
END $label$;
COMMIT;
